public sealed interface CtamreRecord
        permits CtamreRecord.Header, CtamreRecord.Detalle, CtamreRecord.Trailer {

    int LONGITUD = 320;
    String toFixed();

    /** TIPREG 1. FECPROC 9(06) recibe la fecha de máquina, no la de proceso. */
    record Header(int nodoOrigen, LocalDate fecha, String sistemaCliente,   // 9(12): 145886 / 145857
                  int secuencia, String descripcion) implements CtamreRecord {
        public String toFixed() {
            return Fixed.of(LONGITUD).num(1, 1).num(nodoOrigen, 2).fechaAmd6(fecha)
                    .alfaNum(sistemaCliente, 12).num(secuencia, 4).alfa(descripcion, 41)
                    .spaces(254).build();
        }
    }

    /** TIPREG 2. */
    record Detalle(String numAutorizacion,     // 9(08)
                   int sucursalPrefijo, String numCuenta,   // 9(04), 9(12)
                   int naturaleza,             // 1 cargo, 2 abono, 9 no contable, 0 sin catálogo
                   String referencia,          // 9(16)
                   BigDecimal importe,         // 9(14)V99 -> escala 2
                   int sucursalTrans, int cajaTrans,
                   LocalTime horaMov, LocalDate fechaMov,
                   String numAut151, int moneda, String descripcion)
            implements CtamreRecord {
        static final BigDecimal TOPE_IMPORTE = new BigDecimal("99999999999999.99");
        public Detalle {
            if (importe.scale() != 2 || importe.compareTo(TOPE_IMPORTE) > 0)
                throw new IllegalArgumentException("Importe fuera de 9(14)V99: " + importe);
        }
        public String toFixed() { return CtamreLayout.detalle(this); }
    }

    /** TIPREG 9. Conteos 9(08) e importes 9(16)V99, activos y eliminados. */
    record Trailer(Totales activos, Totales eliminados) implements CtamreRecord {
        public String toFixed() { return CtamreLayout.trailer(this); }
    }

    record Totales(long movimientos, long abonos, BigDecimal importeAbonos,
                   long cargos, BigDecimal importeCargos) {}
}

